// The community format (14-community.md section 3) against `contracts/community/vectors.json` (generated by the Python
// reference, `tests/platform/hub/community/vectors.py`): key check, request signature, request and self wraps, a
// message with a non-ASCII body reproduced byte for byte, the broken messages and bodies refused; plus the writer's
// normalisation and every refusal of the reader rules.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { b64uDecode, b64uEncode } from '../../../src/core/encoding/b64u';
import { fromUtf8, utf8 } from '../../../src/core/encoding/bytes';
import { bodyJson } from '../../../src/core/encoding/json';
import * as C from '../../../src/core/crypto/community';
import { ed25519KeyPair, x25519KeyPair } from '../../../src/core/crypto/keys';
import { Secret } from '../../../src/core/crypto/secret';
import { sha256 } from '../../../src/core/crypto/subtle';
import { WEB_DIR } from '../../helpers';
import { codeOf } from './helpers';

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- vector file is untyped JSON
const V: any = JSON.parse(readFileSync(join(WEB_DIR, '..', 'contracts', 'community', 'vectors.json'), 'utf8'));
const b = (text: string) => b64uDecode(text);
const seed = (name: string) => sha256(utf8(`agent.dfx.swiss/vectors/community/${name}`));
const key = () => Secret.of(b(V.community_key));

describe('community vectors', () => {
  it('reproduces the key check and accepts the key', async () => {
    expect(b64uEncode(await C.keyCheck(key(), V.epoch))).toBe(V.key_check);
    expect(await C.matchesCheck(key(), V.epoch, V.key_check)).toBe(true);
    expect(await C.matchesCheck(Secret.random(), V.epoch, V.key_check)).toBe(false);
    expect(await codeOf(() => C.keyCheck(Secret.random(16), 1))).toBe('header_invalid');
  });

  it('reproduces the request text and signature', async () => {
    const request = { id: V.request.id, kem_pub: V.request.kem_pub, user: V.user };
    expect(b64uEncode(C.requestText(request))).toBe(V.request.text);
    const author = await ed25519KeyPair(await seed('author-sig'));
    expect(b64uEncode(author.publicKey)).toBe(V.author_sig_pk);
    expect(await C.signRequest(author.privateKey, request)).toBe(V.request.sig);
    await C.verifyRequest(b(V.author_sig_pk), request, V.request.sig);
    expect(
      await codeOf(() => C.verifyRequest(b(V.author_sig_pk), { ...request, user: V.request.id }, V.request.sig)),
    ).toBe('signature_invalid');
    expect(await codeOf(() => C.requestText({ ...request, kem_pub: 'AAAA' }))).toBe('header_invalid');
    expect(b64uEncode((await x25519KeyPair(b(V.request.kem_sk))).publicKey)).toBe(V.request.kem_pub);
  });

  it('reproduces and opens the request wrap and the self-wrap', async () => {
    const ephemeral = await seed('ephemeral');
    const requestKem = await x25519KeyPair(b(V.request.kem_sk));
    const authorKem = await x25519KeyPair(b(V.author_kem_sk));
    const rw = V.request_wrap;
    expect(await C.wrapCommunityKey(requestKem.publicKey, 1, rw.recipient, key(), ephemeral)).toBe(rw.wrap);
    await C.verifyCommunityWrap(b(rw.wrapper_sig_pk), 1, rw.recipient, rw.wrap, rw.sig);
    const wrapper = await ed25519KeyPair(await seed('wrapper-sig'));
    expect(await C.signCommunityWrap(wrapper.privateKey, 1, rw.recipient, rw.wrap)).toBe(rw.sig);
    const opened = await C.unwrapCommunityKey(requestKem, 1, rw.recipient, rw.wrap);
    expect(await C.matchesCheck(opened, 1, V.key_check)).toBe(true);
    const sw = V.self_wrap;
    expect(await C.wrapCommunityKey(authorKem.publicKey, 1, sw.recipient, key(), ephemeral)).toBe(sw.wrap);
    await C.verifyCommunityWrap(b(V.author_sig_pk), 1, sw.recipient, sw.wrap, sw.sig);
    expect(await codeOf(() => C.verifyCommunityWrap(b(V.author_sig_pk), 1, rw.recipient, sw.wrap, sw.sig))).toBe(
      'signature_invalid',
    );
    expect(await codeOf(() => C.unwrapCommunityKey(authorKem, 1, rw.recipient, sw.wrap))).toBe('decrypt_failed');
  });

  it('reproduces the sealed message and opens it', async () => {
    const author = await ed25519KeyPair(await seed('author-sig'));
    const sealed = V.message.sealed;
    const { salt: _salt, nonce: _nonce, ...fields } = sealed.header;
    expect(C.newHeader(fields)).toEqual(fields);
    expect(fromUtf8(C.bodyBytes(V.message.body.name, V.message.body.text))).toBe(V.message.body_json);
    const mine = await C.sealMessage(key(), fields, utf8(V.message.body_json), author.privateKey, [
      b(sealed.header.salt),
      b(sealed.header.nonce),
    ]);
    expect(mine).toEqual(sealed);
    expect(await C.openMessage(key(), sealed, b(V.author_sig_pk))).toEqual(V.message.body);
    expect(await C.verifyMessage(sealed, b(V.author_sig_pk))).toEqual(sealed.header);
  });

  it('refuses the broken messages', async () => {
    for (const item of V.invalid_messages) {
      expect(await codeOf(() => C.openMessage(key(), item.sealed, b(V.author_sig_pk))), item.name).toBe(item.error);
    }
  });

  it('refuses the broken bodies', async () => {
    for (const item of V.invalid_bodies) {
      expect(await codeOf(() => C.checkBody(item.body)), item.name).toBe('header_invalid');
    }
  });
});

describe('community format rules', () => {
  const author = () => ed25519KeyPair(new Uint8Array(32).fill(7));
  const header = (epoch = 1) =>
    C.newHeader({ id: V.message.sealed.header.id, author: V.user, epoch, ts: V.message.sealed.header.ts });

  it('refuses a body that is not body JSON or breaks a rule', async () => {
    const pair = await author();
    const open = async (plaintext: Uint8Array) =>
      codeOf(async () =>
        C.openMessage(key(), await C.sealMessage(key(), header(), plaintext, pair.privateKey), pair.publicKey),
      );
    expect(await open(utf8('not json'))).toBe('header_invalid');
    expect(await open(utf8('[1]'))).toBe('header_invalid');
    expect(await open(bodyJson({ name: 'A', text: 'x', v: 1 }))).toBe('none');
    expect(await open(bodyJson({ name: 'A', text: 1, v: 1 }))).toBe('header_invalid');
    expect(await codeOf(() => C.checkName('x'.repeat(65)))).toBe('header_invalid');
    expect(await codeOf(() => C.checkName('Zoe\u0308'))).toBe('header_invalid');
    expect(await codeOf(() => C.checkText(' a'))).toBe('header_invalid');
    expect(await codeOf(() => C.checkText('a\u3000'))).toBe('header_invalid');
    expect(C.checkText('a\n\tb')).toBe('a\n\tb');
    expect(await codeOf(() => C.checkText('a\rb'))).toBe('header_invalid');
    expect(await codeOf(() => C.checkText('a\u200Bb'))).toBe('header_invalid');
    expect(C.checkText('ü'.repeat(2000))).toHaveLength(2000);
    expect(C.checkText('😀'.repeat(2000))).toHaveLength(4000);
  });

  it('refuses a wrong key length, salt or ciphertext size', async () => {
    expect(await codeOf(() => C.messageKey(Secret.random(16), new Uint8Array(32)))).toBe('header_invalid');
    expect(await codeOf(() => C.messageKey(key(), new Uint8Array(16)))).toBe('header_invalid');
    const pair = await author();
    expect(await codeOf(() => C.sealMessage(key(), header(), new Uint8Array(C.MAX_CT_BYTES), pair.privateKey))).toBe(
      'size_exceeded',
    );
    expect(await codeOf(() => C.newHeader({ id: 'x', author: V.user, epoch: 1, ts: V.message.sealed.header.ts }))).toBe(
      'header_invalid',
    );
  });

  it('cleans what a writer typed', () => {
    expect(C.cleanName('  Zoe\u0308\u202E \n')).toBe('Zoë');
    expect(C.cleanText('\r\n Hallo\r\nWelt\u200B\u0007\t\r ')).toBe('Hallo\nWelt');
    expect(C.cleanText('a\rb')).toBe('a\nb');
    // removing a format character first lets the rest compose (the result is NFC)
    expect(C.cleanName('e\u200D\u0308')).toBe('\u00EB');
  });
});
